mapper.insert:
INSERT INTO exercise_feedback (
    content,
    exercise_record_id,
    group_member_id
) VALUES (
    #{content},
    #{exerciseRecordId},
    #{groupMemberId}
)

mapper.update:
UPDATE exercise_feedback
SET content = #{content}
WHERE exercise_feedback_id = #{exerciseFeedbackId}

mapper.select:
SELECT COUNT(1) > 0
FROM exercise_feedback
WHERE exercise_record_id = #{exerciseRecordId}

mapper.delete:
DELETE FROM exercise_feedback
WHERE group_member_id IN (
SELECT group_member_id
FROM group_member
WHERE group_id = #{groupId}
)
